#!/bin/sh
# Regenerates src/pdf_fonts_embedded.c/.h from the TTF files in src/fonts/.
# Run this only when a vendored font file changes; the generated files are
# checked into git like configure is, so a normal build never needs xxd.
#
# Font choice: Liberation Sans/Sans Italic/Mono, not DejaVu -- Liberation is
# purpose-built metric-compatible with Helvetica/Helvetica-Oblique/Courier
# (verified directly via fontTools: Liberation's per-glyph advance widths
# match Adobe's Core14 AFM tables almost exactly, DejaVu's do not). Several
# places in pretty.c/pretty_report.c draw a long, fixed, unwrapped string
# relying on it fitting the page under Helvetica's specific metrics with no
# dynamic width check -- DejaVu Sans is measurably wider and made at least
# one real citation line overflow the page border. Liberation avoids that
# whole risk instead of requiring an audit of every such string.
set -e
cd "$(dirname "$0")/.."
OUT_C=src/pdf_fonts_embedded.c
OUT_H=src/pdf_fonts_embedded.h

gen_array () {
    # $1 = ttf file, $2 = canonical C name
    xxd -i "$1" | sed \
        -e "s/^unsigned char [A-Za-z0-9_]*\[\]/const unsigned char $2[]/" \
        -e "s/^unsigned int [A-Za-z0-9_]*_len/const unsigned int ${2}_len/"
}

{
    echo "/* Auto-generated by tools/generate_embedded_fonts.sh -- do not hand-edit."
    echo "   Embeds the Liberation fonts (src/fonts/, see"
    echo "   LiberationFonts-LICENSE.txt) so pdf_init() can give migrate's PDF"
    echo "   report real embedded font programs (ISO 14289-1:2014 7.21.4.1),"
    echo "   instead of relying on libharu's un-embeddable Standard-14 fonts."
    echo "   Liberation Sans/Sans Italic/Mono are metric-compatible with"
    echo "   Helvetica/Helvetica-Oblique/Courier by design, so this is a"
    echo "   layout-preserving swap, not just a visual one. */"
    echo "#include \"pdf_fonts_embedded.h\""
    echo
    gen_array src/fonts/LiberationSans-Regular.ttf pdf_font_helv_ttf
    echo
    gen_array src/fonts/LiberationSans-Italic.ttf pdf_font_helvob_ttf
    echo
    gen_array src/fonts/LiberationMono-Regular.ttf pdf_font_cour_ttf
} > "$OUT_C"

{
    echo "/* Auto-generated by tools/generate_embedded_fonts.sh -- do not hand-edit. */"
    echo "#ifndef PDF_FONTS_EMBEDDED_H"
    echo "#define PDF_FONTS_EMBEDDED_H"
    echo
    for name in pdf_font_helv_ttf pdf_font_helvob_ttf pdf_font_cour_ttf; do
        echo "extern const unsigned char ${name}[];"
        echo "extern const unsigned int ${name}_len;"
    done
    echo
    echo "#endif"
} > "$OUT_H"

echo "Wrote $OUT_C and $OUT_H"
